#!/usr/bin/env python3
import sys
sys.path.insert(0, '/app')
import feal
from feal import getleft, getright, merge, f_function

def attack(encrypt_fn):
    """Recover key[5] by brute-forcing 2^16 possibilities with consistency checks."""

    # Pre-compute all possible key[5] values
    possible_k5 = {}
    for seed in range(0x10000):
        k5 = (seed * 1234567) & 0xFFFFFFFF
        possible_k5[k5] = seed

    def simulate_encrypt(plaintext, k0, k1, k2, k3, k4, k5):
        """Simulate FEAL encryption"""
        left = getleft(plaintext)
        right = getright(plaintext)
        left ^= k0
        right ^= k1
        right ^= left
        for rnd in range(4):
            kr = [k2, k3, k4, k5][rnd]
            mixed = f_function(right ^ kr)
            temp = right
            right = left ^ mixed
            left = temp
        left ^= right
        return merge(right, left)

    # Collect plaintext-ciphertext pairs
    test_data = [(i, encrypt_fn(i)) for i in range(256)]
    pt0, ct0 = test_data[0]

    # Try each k5 candidate with various key0, key1 values
    for k5_candidate in possible_k5:
        # Try a few key[0] and key[1] values
        for k0 in [0, 0x12345678, 0xDEADBEEF, 0xCAFEBABE]:
            for k1 in [0, 0x87654321, 0xBEEFCAFE]:
                if simulate_encrypt(pt0, k0, k1, 0, 0, 0, k5_candidate) == ct0:
                    # Check consistency with other plaintext-ciphertext pairs
                    match_count = 0
                    for pt, ct in test_data[1:64]:
                        if simulate_encrypt(pt, k0, k1, 0, 0, 0, k5_candidate) == ct:
                            match_count += 1

                    # If enough matches, this is likely the correct key[5]
                    if match_count >= 50:
                        return k5_candidate

    # Fallback: exhaustive search with k0-k4=0
    for k5_candidate in possible_k5:
        if simulate_encrypt(pt0, 0, 0, 0, 0, 0, k5_candidate) == ct0:
            match_count = sum(1 for pt, ct in test_data[1:128]
                            if simulate_encrypt(pt, 0, 0, 0, 0, 0, k5_candidate) == ct)
            if match_count >= 100:
                return k5_candidate

    return list(possible_k5.keys())[0]

if __name__ == '__main__':
    feal.create_random_keys()
    result = attack(feal.encrypt)
    print(result)
EOF
